import { enqueueTask } from '@projexlight/sdk-dispatch';
const t = await enqueueTask({
  tenant_id, customer_ref, address,
  geo: { lat, lng },
  skill_required: 'hvac-residential',
  priority: 'standard',
  sla_deadline: new Date(Date.now() + 24*3600e3),
});

// driven by event subscription:
subscribeEvents('storm.event.spawned.v1', async (e) => {
  for (const cust of affectedCustomers(e.payload)) {
    await enqueueTask({
      tenant_id: e.tenant_id, customer_ref: cust.id, address: cust.address,
      geo: cust.geo, skill_required: 'storm-triage', priority: 'critical',
      sla_deadline: storm_response_sla(cust.tier),
    });
  }
});

import { materializeRoute } from '@projexlight/sdk-dispatch';
const route = await materializeRoute({
  tenant_id, tech_persona_id, date: '2026-05-26',
  max_stops: 8,
});

// driven by event subscription on assignment.assignment.claimed.v1:
subscribeEvents('assignment.assignment.claimed.v1', async (e) => {
  await markDispatched({ task_id: e.payload.task_id, claimed_by: e.payload.assigned_to });
});

import { completeTask } from '@projexlight/sdk-dispatch';
await completeTask({
  tenant_id, task_id,
  completed_by_persona_id, evidence_ids: [...],
  notes: 'replaced capacitor, system tested green',
});
